98	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
99	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
100	     */
101	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
102	        "NSW", new int[] {2000, 2099},
103	        "VIC", new int[] {3000, 3099},
104	        "QLD", new int[] {4000, 4099});
105	
106	    /** Dedicated audit logger; one line is emitted per successful owner create. */
107	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
108	
109	    /** Dedicated notification logger; one welcome line is emitted per successful owner create. */
110	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
111	
112	    /**
113	     * Monotonically increasing sequence for structured owner-create events, shared across all creates
114	     * regardless of which request or thread performs them. The first event carries {@code seq=1}.
115	     */
116	    private static final AtomicInteger OWNER_CREATE_SEQUENCE = new AtomicInteger();
117	
118	    /** Serializer for the immutable structured audit event. */
119	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
120	
121	    /**
122	     * The maximum number of owners a single city may contain. Once a city already holds this many
123	     * owners, any further create naming that city is rejected as a conflict.
124	     */
125	    private static final int MAX_OWNERS_PER_CITY = 50;
126	
127	    /**
128	     * The number of owners a city must already hold before a response carries a capacity warning.
129	     * Once a city holds at least this many owners (but fewer than {@link #MAX_OWNERS_PER_CITY}),
130	     * responses naming that city set {@code capacityWarning} true, signalling that the city is
131	     * approaching its per-city capacity limit.
