149	     * The fixed list of public holidays. A registration date that lands on one of these dates is
150	     * rolled forward to the next non-holiday business day, just as a weekend date is.
151	     */
152	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
153	        LocalDate.of(2026, 1, 1),
154	        LocalDate.of(2026, 1, 26),
155	        LocalDate.of(2026, 4, 25),
156	        LocalDate.of(2026, 12, 25),
