195	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        OwnerDto ownerDto = toOwnerDto(owner);
201	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
202	        ownerDto.setCapacityWarning(isCapacityWarningActive(owner.getCity()));
203	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
