206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
209	        String idempotencyKey = currentIdempotencyKey();
210	        if (idempotencyKey != null) {
211	            Owner alreadyCreated = findOwnerByIdempotencyKey(idempotencyKey);
212	            if (alreadyCreated != null) {
213	                OwnerDto existingDto = toOwnerDto(alreadyCreated);
214	                existingDto.setBulkSignupWarning(isBulkSignupWarningActive());
215	                existingDto.setCapacityWarning(isCapacityWarningActive(alreadyCreated.getCity()));
216	                return new ResponseEntity<>(existingDto, HttpStatus.OK);
217	            }
218	        }
219	        validateRequiredOwnerFields(ownerFieldsDto);
220	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
221	        LocalDate suppliedOrDefaultDate =
222	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
223	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
224	        rejectDailyLimitExceeded(registrationDate);
225	        rejectCityAtCapacity(ownerFieldsDto.getCity());
226	        HttpHeaders headers = new HttpHeaders();
227	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
228	        validatePostcode(owner.getCity(), owner.getPostcode());
229	        applyAddress(owner);
230	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
231	        owner.setTelephone(normalizedTelephone);
232	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
233	        owner.setEmail(normalizeEmail(owner.getEmail()));
234	        rejectDuplicateIdentity(owner);
235	        applyPossibleDuplicate(owner, declaredHouseholdMember);
236	        owner.setRegistrationDate(registrationDate);
237	        owner.setMemberId(generateMemberId(owner.getPostcode(), owner.getCity(), normalizedTelephone,
238	            owner.getLastName(), owner.getRegistrationDate()));
239	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
240	        owner.setIdempotencyKey(idempotencyKey);
241	        applyMembershipLevelCeiling(owner);
242	        this.clinicService.saveOwner(owner);
243	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
244	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
245	        emitOwnerCreatedEvent(owner);
246	        enqueueWelcomeNotification(owner);
247	        OwnerDto ownerDto = toOwnerDto(owner);
248	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
249	        ownerDto.setCapacityWarning(isCapacityWarningActive(owner.getCity()));
250	        headers.setLocation(UriComponentsBuilder.newInstance()
251	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
252	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
253	    }
254	
255	    /**
256	     * Emits the immutable structured {@code OWNER_CREATED} event on the {@code AUDIT} logger, in
257	     * addition to the human-readable audit line. The event carries a monotonically increasing sequence
258	     * number, the owner id, the owner's current primary identifier (the member id) and the derived
259	     * membership level, serialized as a compact JSON object.
260	     *
261	     * @param owner the just-saved owner
262	     */
263	    private void emitOwnerCreatedEvent(Owner owner) {
264	        OwnerCreatedEvent event = OwnerCreatedEvent.of(OWNER_CREATE_SEQUENCE.incrementAndGet(),
265	            owner.getId(), owner.getMemberId(), owner.getMembershipLevel());
266	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
267	    }
268	
269	    /**
270	     * Enqueues a welcome notification for a just-created owner by emitting a single line on the
271	     * {@code NOTIFY} logger carrying the owner id and the owner's member id.
272	     *
273	     * @param owner the just-saved owner
