512	    /**
513	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
514	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
515	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
516	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
517	     *
518	     * @return {@code true} when more than the threshold number of owners are already registered on
519	     *         today's business day, otherwise {@code false}
520	     */
521	    private boolean isBulkSignupWarningActive() {
522	        LocalDate today = toBusinessDay(LocalDate.now());
523	        long ownersToday = this.clinicService.findAllOwners().stream()
524	            .filter(existing -> today.equals(existing.getRegistrationDate()))
