549	    private LocalDate toBusinessDay(LocalDate date) {
550	        LocalDate adjusted = switch (date.getDayOfWeek()) {
551	            case SATURDAY -> date.plusDays(2);
552	            case SUNDAY -> date.plusDays(1);
553	            default -> date;
554	        };
555	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
556	            adjusted = adjusted.plusDays(1);
557	        }
558	        return adjusted;
559	    }
