578	    /**
579	     * Builds an owner's unified member id, formatted '&lt;REGION&gt;&lt;FY&gt;&lt;HASH8&gt;&lt;CHK&gt;'.
580	     * REGION is the region code derived from the owner's postcode (falling back to their city; see
581	     * {@link LocalityLookup}); FY is the two-digit fiscal year (the fiscal year starts on 1 July) that
582	     * the business-day-adjusted registrationDate falls in; HASH8 is the first 8 upper-case hex
583	     * characters of the SHA-256 digest over the owner's normalized telephone concatenated with their
584	     * last name (the same hash used by the region-and-hash identity); and CHK is a single Luhn check
585	     * digit computed over the digits of '&lt;REGION&gt;&lt;FY&gt;&lt;HASH8&gt;' (e.g. 'NSW271A2B3C4D5').
586	     * When the computed id collides with an existing owner's member id it is de-duplicated by appending
587	     * '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
588	     *
589	     * @param postcode the owner's postcode, used first to derive the region
590	     * @param city the owner's city, used to derive the region when the postcode maps to none
591	     * @param normalizedTelephone the owner's normalized (E.164) telephone
592	     * @param lastName the owner's last name
593	     * @param registrationDate the owner's business-day-adjusted registration date
594	     * @return the formatted, de-duplicated member id
595	     */
596	    private String generateMemberId(String postcode, String city, String normalizedTelephone, String lastName,
597	            LocalDate registrationDate) {
598	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
599	        String fy = String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
600	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
601	        String base = region + fy + hash8;
602	        String baseId = base + luhnCheckDigit(base);
603	        return deduplicateMemberId(baseId);
604	    }
605	
606	    /**
607	     * De-duplicates a computed member id against every existing owner's member id. When no existing
608	     * owner already carries the base id it is returned unchanged; otherwise '-&lt;n&gt;' is appended
609	     * with the smallest {@code n} of 2 or more that yields an id no existing owner holds.
610	     *
611	     * @param baseId the computed, formatted member id before de-duplication
612	     * @return the base id when unique, otherwise the base id suffixed with '-&lt;n&gt;'
613	     */
614	    private String deduplicateMemberId(String baseId) {
615	        java.util.Set<String> existingIds = this.clinicService.findAllOwners().stream()
616	            .map(Owner::getMemberId)
617	            .filter(java.util.Objects::nonNull)
618	            .collect(java.util.stream.Collectors.toSet());
619	        if (!existingIds.contains(baseId)) {
620	            return baseId;
621	        }
622	        int n = 2;
623	        while (existingIds.contains(baseId + "-" + n)) {
624	            n++;
625	        }
626	        return baseId + "-" + n;
627	    }
628	
629	    /**
630	     * The single Luhn check digit (0-9) computed over the digits contained in the given string.
631	     * Non-digit characters are ignored and the rightmost digit is doubled.
632	     *
633	     * @param value the string whose digits the check digit is computed over
634	     * @return the Luhn check digit (0-9)
635	     */
636	    private int luhnCheckDigit(String value) {
637	        int sum = 0;
638	        boolean dbl = true;
639	        for (int i = value.length() - 1; i >= 0; i--) {
640	            char c = value.charAt(i);
641	            if (c < '0' || c > '9') {
642	                continue;
643	            }
644	            int d = c - '0';
645	            if (dbl) {
646	                d *= 2;
647	                if (d > 9) {
648	                    d -= 9;
649	                }
650	            }
651	            sum += d;
652	            dbl = !dbl;
653	        }
654	        return (10 - (sum % 10)) % 10;
655	    }
