657	    /**
658	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
659	     * country calling code. Australia ('+61') uses 9 national digits and the North American
660	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
661	     * E.164 length (8 to 15 digits overall).
662	     */
663	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
664	        java.util.Map.of("61", 9, "1", 10);
665	
666	    /**
667	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
668	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
669	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
670	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
671	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
672	     * E.164 string is what gets stored and returned.
673	     *
674	     * @param telephone the raw telephone value from the request
675	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
676	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
677	     *         national number has the wrong length for its country code
678	     */
679	    private String normalizeTelephone(String telephone) {
680	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
681	        String e164;
682	        if (cleaned.startsWith("+")) {
683	            e164 = cleaned;
684	        } else {
685	            String national = cleaned;
686	            if (national.startsWith("0")) {
687	                national = national.substring(1);
688	            }
689	            e164 = "+61" + national;
690	        }
691	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
692	            throw new InvalidOwnerFieldsException(List.of("telephone"));
693	        }
694	        validateNationalNumberLength(e164);
695	        return e164;
696	    }
697	
698	    /**
699	     * Rejects an E.164 telephone whose national number does not have the exact length its country
700	     * calling code requires. The digits after the leading '+' are split into the longest matching
701	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
702	     * code is known and the national number's length differs from the required count the telephone is
703	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
704	     *
705	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
706	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
707	     */
708	    private void validateNationalNumberLength(String e164) {
709	        String digits = e164.substring(1);
710	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
711	            String countryCode = digits.substring(0, codeLength);
712	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
713	            if (requiredNationalLength != null) {
714	                int nationalLength = digits.length() - codeLength;
715	                if (nationalLength != requiredNationalLength) {
716	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
717	                }
718	                return;
719	            }
720	        }
721	    }
722	
723	    /**
724	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
725	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
726	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
727	     * stored and returned is the value lower-cased.
728	     *
729	     * @param email the raw email value from the request, or {@code null} when none was supplied
730	     * @return the lower-cased email, or {@code null} when no email was supplied
731	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
732	     *         its domain is on the disposable-domain blocklist
733	     */
734	    private String normalizeEmail(String email) {
735	        if (email == null || email.isBlank()) {
736	            return null;
737	        }
738	        if (!EMAIL_PATTERN.matcher(email).matches()) {
739	            throw new InvalidOwnerFieldsException(List.of("email"));
740	        }
741	        String normalized = email.toLowerCase(Locale.ROOT);
742	        String domain = normalized.substring(normalized.indexOf('@') + 1);
743	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
744	            throw new InvalidOwnerFieldsException(List.of("email"));
745	        }
746	        return normalized;
747	    }
748	
749	    /**
750	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
751	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
752	     * When present it must be exactly four digits and, when the owner's city maps to a known region
753	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
754	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
755	     * region accepts any four-digit postcode.
756	     *
757	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
758	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
759	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
760	     *         for the city's region
761	     */
762	    private void validatePostcode(String city, String postcode) {
763	        if (postcode == null || postcode.isBlank()) {
764	            return;
765	        }
766	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
767	            throw new InvalidOwnerFieldsException(List.of("postcode"));
768	        }
769	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
770	        if (range == null) {
771	            return;
772	        }
773	        int value = Integer.parseInt(postcode);
774	        if (value < range[0] || value > range[1]) {
775	            throw new InvalidOwnerFieldsException(List.of("postcode"));
776	        }
777	    }
