779	    /**
780	     * Resolves an owner's address from the supplied structured and flat fields, preferring the
781	     * structured form. Whichever address fields were supplied are normalized (see
782	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
783	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (an
784	     * absent or blank {@code addressLine2} is cleared) and the composed {@code address} is the
785	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
786	     * appended when the latter is present. When no {@code addressLine1} is supplied the flat
787	     * {@code address} is used unchanged for backward compatibility and the structured lines are
788	     * cleared. The composed {@code address} is what every later step reads.
789	     *
790	     * @param owner the owner being created, mapped from the request but not yet normalized
791	     */
792	    private void applyAddress(Owner owner) {
793	        String line1 = normalizeAddress(owner.getAddressLine1());
794	        String line2 = normalizeAddress(owner.getAddressLine2());
795	        String flat = normalizeAddress(owner.getAddress());
796	        if (!line1.isEmpty()) {
797	            owner.setAddressLine1(line1);
798	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
799	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
800	        } else {
801	            owner.setAddressLine1(null);
802	            owner.setAddressLine2(null);
803	            owner.setAddress(flat);
804	        }
805	    }
806	
807	    /**
808	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
809	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
810	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
811	     * normalized form is what gets stored, returned and used for every address comparison (the
812	     * required-field check, household duplicate detection and the shared household id).
813	     *
814	     * @param address the raw address value from the request, or {@code null}
815	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
816	     */
817	    private String normalizeAddress(String address) {
818	        if (address == null) {
819	            return "";
820	        }
821	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
822	        if (collapsed.isEmpty()) {
823	            return "";
824	        }
825	        String[] tokens = collapsed.split(" ");
826	        for (int i = 0; i < tokens.length; i++) {
827	            switch (tokens[i]) {
828	                case "ST" -> tokens[i] = "STREET";
829	                case "RD" -> tokens[i] = "ROAD";
830	                case "AVE" -> tokens[i] = "AVENUE";
831	                default -> { }
832	            }
833	        }
834	        return String.join(" ", tokens);
835	    }
836	
837	    /**
838	     * Rejects an owner create whose {@code identityKey} exactly matches a non-deleted existing owner's.
839	     * The identity key - the SHA-256 hex digest over the owner's normalized telephone, lower-cased email
840	     * (empty when none) and the Soundex code of its last name, joined by {@code '|'} - is the single
841	     * derived value used for duplicate detection; owners flagged deleted are ignored. Only a whole-key
842	     * match is a conflict, so two owners with the same last name and postcode but different telephones
843	     * have different keys and are both allowed; only an owner whose entire key is identical is a
844	     * duplicate.
845	     *
846	     * @param owner the owner being created, with its telephone, email and last name already resolved
847	     * @throws DuplicateOwnerIdentityException if another non-deleted owner already has this exact identity key
848	     */
849	    private void rejectDuplicateIdentity(Owner owner) {
850	        String identityKey = owner.getIdentityKey();
851	        boolean inUse = this.clinicService.findAllOwners().stream()
852	            .filter(existing -> !existing.isDeleted())
853	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
854	        if (inUse) {
855	            throw new DuplicateOwnerIdentityException(identityKey);
856	        }
857	    }
858	
859	    /**
860	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
861	     * whose last name shares this owner's Soundex code and whose postcode matches, yet whose
862	     * {@code identityKey} differs; such an owner is not a hard duplicate (its whole identity key
863	     * differs) and is still created. When at least one soft match exists, {@code possibleDuplicate} is
864	     * set true and {@code possibleDuplicateOf} to the lowest-id match; otherwise {@code possibleDuplicate}
865	     * is false and {@code possibleDuplicateOf} is left unset.
866	     * <p>
867	     * A declared household member - an owner that acknowledged sharing an existing household via
868	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
869	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
870	     *
871	     * @param owner the owner being created, with its last name, postcode, email and normalized
872	     *        telephone resolved
873	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
874	     */
875	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
876	        if (declaredHouseholdMember) {
877	            owner.setPossibleDuplicate(false);
878	            return;
879	        }
880	        String soundex = Owner.soundex(owner.getLastName());
881	        String postcode = owner.getPostcode();
882	        String identityKey = owner.getIdentityKey();
883	        Owner match = null;
884	        if (postcode != null && !postcode.isBlank()) {
885	            match = this.clinicService.findAllOwners().stream()
886	                .filter(existing -> !existing.isDeleted())
887	                .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex))
888	                .filter(existing -> postcode.equals(existing.getPostcode()))
889	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
890	                .min(java.util.Comparator.comparing(Owner::getId))
891	                .orElse(null);
892	        }
893	        if (match != null) {
894	            owner.setPossibleDuplicate(true);
895	            owner.setPossibleDuplicateOf(match.getId());
896	        } else {
897	            owner.setPossibleDuplicate(false);
898	        }
899	    }
900	
901	    /**
902	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
903	     * household member count} for the response.
904	     *
905	     * @param owner the owner to map
906	     * @return the mapped owner DTO
907	     */
908	    private OwnerDto toOwnerDto(Owner owner) {
909	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
910	        return ownerMapper.toOwnerDto(owner);
911	    }
912	
913	    /**
914	     * Counts the members of the given owner's household - the owners that share this owner's
915	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
916	     * is {@code null}) is its own sole member, so the count is one.
917	     *
918	     * @param owner the owner whose household is being sized
919	     * @return the number of owners sharing this owner's household (one when it has no household)
920	     */
921	    private int countHouseholdMembers(Owner owner) {
922	        String householdId = owner.getHouseholdId();
923	        if (householdId == null) {
924	            return 1;
925	        }
926	        return (int) this.clinicService.findAllOwners().stream()
927	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
928	            .count();
929	    }
930	
931	    /**
932	     * Caps the membership level of an owner being created so it can never exceed one above the current
933	     * maximum membership level among the other members of its household. The ceiling stored is that
934	     * maximum plus one; the owner's derived {@link Owner#getMembershipLevel() membership level} is then
935	     * never reported above it. An owner that joined no existing household - it has no {@code householdId}
936	     * or is the sole member of its household - is left uncapped so no ceiling applies.
937	     *
938	     * @param owner the owner being created, with its {@code householdId} already resolved
939	     */
940	    private void applyMembershipLevelCeiling(Owner owner) {
941	        String householdId = owner.getHouseholdId();
942	        if (householdId == null) {
943	            return;
944	        }
945	        OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
946	            .filter(existing -> !existing.isDeleted())
947	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
948	            .mapToInt(this::currentMembershipLevel)
949	            .max();
950	        if (maxLevel.isPresent()) {
951	            owner.setMembershipLevelCeiling(maxLevel.getAsInt() + 1);
952	        }
953	    }
954	
955	    /**
956	     * The membership level an existing owner currently reports, computed the same way as for a response
957	     * by first populating its {@link Owner#getHouseholdMemberCount() household member count}.
958	     *
959	     * @param member the existing household member whose membership level is needed
960	     * @return the member's current membership level
961	     */
962	    private int currentMembershipLevel(Owner member) {
963	        member.setHouseholdMemberCount(countHouseholdMembers(member));
964	        return member.getMembershipLevel();
965	    }
966	
967	    /**
968	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
969	     * last name and a postcode: the {@code householdId} is derived deterministically from the
970	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
971	     * owners with the same last name and postcode always resolve to the same identifier and belong to
972	     * the same household automatically - no acknowledgement is needed to create the link.
973	     * <p>
974	     * When the owner supplies a postcode its {@code householdId} is always assigned; an owner with no
975	     * postcode belongs to no household and is left without an identifier. Joining an existing household
976	     * is not itself a conflict: hard duplicate detection is handled solely by the identity key (see
977	     * {@link #rejectDuplicateIdentity(Owner)}), so two members of one household with different
978	     * telephones are both created. An owner that explicitly acknowledges an existing household via
979	     * {@code sharesHousehold} is reported as a declared member so it is not flagged as a possible
980	     * duplicate.
981	     *
982	     * @param owner the owner being created
983	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
984	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
985	     *         {@code false}
986	     */
987	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
988	        String postcode = owner.getPostcode();
989	        if (postcode == null || postcode.isBlank()) {
990	            return false;
991	        }
992	        String lastName = normalizeHouseholdField(owner.getLastName());
993	        String householdId = generateHouseholdId(lastName, postcode);
994	        owner.setHouseholdId(householdId);
995	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
996	            .filter(existing -> !existing.isDeleted())
997	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
998	        return hasExistingMember && Boolean.TRUE.equals(sharesHousehold);
999	    }
1000	
1001	    /**
1002	     * Builds the stable identifier shared by the members of one household. It is derived purely from
1003	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
1004	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
1005	     * two fields joined by a single '|'.
1006	     *
1007	     * @param normalizedLastName the household's last name, already normalized for comparison
1008	     * @param postcode the household's postcode
1009	     * @return the shared household identifier
1010	     */
1011	    private String generateHouseholdId(String normalizedLastName, String postcode) {
1012	        String key = normalizedLastName + '|' + postcode;
1013	        try {
1014	            byte[] digest = MessageDigest.getInstance("SHA-256")
1015	                .digest(key.getBytes(StandardCharsets.UTF_8));
1016	            StringBuilder hex = new StringBuilder();
1017	            for (byte b : digest) {
1018	                hex.append(String.format("%02X", b));
1019	                if (hex.length() >= 12) {
1020	                    break;
1021	                }
1022	            }
1023	            return hex.substring(0, 12);
1024	        } catch (NoSuchAlgorithmException e) {
1025	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
1026	        }
1027	    }
1028	
1029	    /**
1030	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
1031	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
1032	     * the owner's normalized telephone and last name.
1033	     *
1034	     * @param input the string to digest
1035	     * @param length the number of leading upper-case hex characters to return
1036	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
1037	     */
1038	    private String sha256UpperHex(String input, int length) {
1039	        try {
1040	            byte[] digest = MessageDigest.getInstance("SHA-256")
1041	                .digest(input.getBytes(StandardCharsets.UTF_8));
1042	            StringBuilder hex = new StringBuilder();
1043	            for (byte b : digest) {
1044	                hex.append(String.format("%02X", b));
1045	                if (hex.length() >= length) {
1046	                    break;
1047	                }
1048	            }
1049	            return hex.substring(0, length);
1050	        } catch (NoSuchAlgorithmException e) {
1051	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
1052	        }
1053	    }
1054	
1055	    /**
1056	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
1057	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
1058	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
1059	     * expands common abbreviations.
1060	     *
1061	     * @param value the raw last name, or {@code null}
1062	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
1063	     */
1064	    private String normalizeHouseholdField(String value) {
1065	        if (value == null) {
1066	            return "";
1067	        }
1068	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1069	    }
1070	}
